int main(int argc,char**argv){Assets assets;if(argc>1)assets.root=std::string(argv[1])+"/";JavaSoundBank bank;JavaSoundBank::Variant v;SoundDesc sound;assert(bank.select(&assets,"minecraft:item.mace.smash_ground_heavy",42,v,sound,true));assert(sound.isValid()&&sound.channels==1&&sound.byteWidth==2&&sound.frameRate==(argc>1?48000:44100)&&sound.size>0);auto first=v.file;assert(bank.select(&assets,"minecraft:item.mace.smash_ground_heavy",42,v,sound,true)&&v.file==first);assert(bank.select(&assets,"minecraft:entity.wind_charge.wind_burst",0xffffffffffffffffULL,v,sound,true));assert(v.pitch==1.25f&&v.distance==8.f);assert(bank.select(&assets,"minecraft:item.spear.hit",773,v,sound,true));assert(bank.select(&assets,"tcpe:step.grass",17,v,sound,true));assert(!bank.select(&assets,"custom:unprovided_boss_sound",1,v,sound,true));std::vector<unsigned char> broken(44,0);size_t offset,size;int rate,channels;assert(!JavaSoundBank::wav(broken,offset,size,rate,channels));JavaPackSounds lower,upper;JavaPackSoundSample custom;custom.name="custom:clip";custom.file="0123456789abcdef01234567.wav";custom.channels=2;custom.rate=32000;custom.pcm={1,0,2,0,3,0,4,0};lower.samples.push_back(custom);JavaPackSoundDefinition d;d.name="custom:event";JavaPackSoundVariant a;a.name="custom:clip";a.volume=.5f;a.pitch=1.5f;d.variants.push_back(a);lower.definitions.push_back(d);JavaPackSoundDefinition alias;alias.name="custom:alias";JavaPackSoundVariant ref;ref.name="custom:event";ref.kind="event";ref.weight=999;ref.volume=.5f;alias.variants.push_back(ref);lower.definitions.push_back(alias);
bank.apply(&assets,{&lower});assert(bank.select(&assets,"custom:alias",17,v,sound,true));assert(sound.channels==2&&sound.frameRate==32000&&sound.size==8&&v.volume==.25f&&v.pitch==1.5f);assert(bank.registrations().size()==1);upper.definitions.push_back(d);upper.definitions.back().replace=true;upper.definitions.back().variants.clear();bank.apply(&assets,{&lower,&upper});assert(!bank.select(&assets,"custom:event",17,v,sound,true));bank.apply(&assets,{&upper,&lower});assert(bank.select(&assets,"custom:event",17,v,sound,true));bank.clear();assert(!bank.select(&assets,"custom:event",17,v,sound,true));assert(bank.select(&assets,"minecraft:item.mace.smash_ground_heavy",42,v,sound,true));
JavaPackSounds damaged;JavaPackSoundSample missing;missing.name="minecraft:step/wood1";damaged.samples.push_back(missing);JavaPackSoundDefinition brokenAlias;brokenAlias.name="custom:bad";JavaPackSoundVariant missingRef;missingRef.name=missing.name;brokenAlias.variants.push_back(missingRef);damaged.definitions.push_back(brokenAlias);bank.apply(&assets,{&damaged});assert(!bank.select(&assets,"custom:bad",17,v,sound,true));bank.apply(&assets,{&damaged,&lower});auto mixture=lower.definitions[0];mixture.name="custom:mixture";mixture.variants.push_back(missingRef);damaged.definitions.push_back(mixture);bank.apply(&assets,{&lower,&damaged});int valid=0;for(uint64_t seed=0;seed<64;++seed)if(bank.select(&assets,"custom:mixture",seed*173,v,sound,true))++valid;assert(valid>0&&valid<64);bank.clear();assert(bank.select(&assets,"minecraft:block.wood.step",42,v,sound,true));
std::cout<<"canonical mace/wind/spear/legacy WAV lookup, seed determinism, gain metadata and malformed WAV guards passed\n";}
